SC.trophyData({"format":"soulscraft-trophies","version":2,"source":"docs/design/09-trophies.md; шансы — предложения до утверждения","diorama":{"name":"Диорама","text":"Кусочек родных мест моба на подставке из тёмного дерева с латунными углами и гравированной табличкой. Моб стоит в трофейной позе и медленно дышит; сцена светится и пускает частицы: туман, искры, снег, пузыри.","item":"Предмет — сама диорама: ставится как блок и смотрит на игрока","plaque":"имя моба и число убийств владельца из книги охотника; текст рисует мод","view_blocks":64,"particles_blocks":32},"rejected":{"round":6,"commit":"5c92192","text":"Раунд 6: автор выбрал диораму. Фигурка на постаменте (А), бюст на щите (Б) и фигурка в позе атаки (Г) отвергнуты: их блоков и полей в файле трофея больше нет. Картинка вариантов — assets/models/previews/trophy_sheet.png в коммите 5c92192.","variants":["А. Фигурка на постаменте","Б. Бюст на щите","Г. Фигурка в позе атаки"]},"drops":{"head":{"event":"гарантированно за победу: голова одного из мобов ивента, плюс по одной за каждое знамя «сложнее»","world":0.01,"world_elite":0.03},"armor":{"event":0.3,"world":"как в бестиарии"},"diorama":{"event":"только за победу на алтаре 3-го уровня и выше: диорама одного моба ивента","min_altar_level":3,"world":null}}});
SC.bookData({"format":"soulscraft-book","version":1,"source":"docs/design/08-guide-book.md; пороги — гипотеза Г11","item":"soulscraft:hunter_book","sections":["Враги","Алтарь","Ивенты"],"stages":[{"id":"unknown","n":0,"name":"Неизвестен","kills":null,"elite_kills":null,"when":"—","opens":"Силуэт и «???»: игрок знает, что ещё есть что искать"},{"id":"met","n":1,"name":"Встречен","kills":0,"elite_kills":0,"when":"Моб был в 16 блоках и видел игрока, или ударил игрока","opens":"Имя, образ, где водится, модель в покое"},{"id":"killed","n":2,"name":"Убит","kills":1,"elite_kills":1,"when":"1 убийство","opens":"Здоровье, урон, броня; список атак без подробностей; клипы покоя и шага"},{"id":"studied","n":3,"name":"Изучен","kills":5,"elite_kills":3,"when":"5 убийств (элитный — 3)","opens":"Каждая атака с анимацией и шкалой фаз: замах, пауза, удар, окно игрока; как читать замах"},{"id":"expert","n":4,"name":"Знаток","kills":15,"elite_kills":8,"when":"15 убийств (элитный — 8)","opens":"Тактика против моба, добыча, рост по силе P, связь с ивентами"}],"credit":{"radius_blocks":32,"window_seconds":10,"spawner_weight":0.25},"altar_entries":[{"id":"altar","name":"Алтарь: основа","when":"Игрок взял в руки предмет призыва или блок алтаря"},{"id":"levels","name":"Уровни 1–4","when":"Игрок впервые достроил алтарь до этого уровня или был рядом, когда его достроили"},{"id":"modifiers","name":"Знамёна-модификаторы","when":"Игрок впервые держал знамя в руках"},{"id":"defense","name":"Оборона алтаря","when":"Первый старт ивента рядом с игроком","text":"Враги волны идут к алтарю. Кто подошёл к вам ближе шести блоков или получил удар, дерётся с вами, остальные идут дальше. У алтаря враг встаёт и тянет из него силу: ударьте его, и он собьётся. Стены — хорошая защита, если оставить врагам путь: постройте лабиринт, который ведёт их мимо турелей и мимо вас. Если закрыться наглухо, запертые враги начнут тянуть проклятие сквозь стены издалека, а громила проломит стену. Сломанные громилой блоки встанут на место после ивента."},{"id":"events","name":"Ивенты","when":"Описание — после первой попытки; список волн и награда — после первой победы"}],"action_bar":"Книга охотника: {mob} — {stage}"});
